BEGIN;
CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS revrec_tenants(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS revrec_memberships(tenant_id BIGINT NOT NULL REFERENCES revrec_tenants(id),user_id INTEGER NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN('revrec_accountant','controller','posting_operator','auditor','admin')),active BOOLEAN NOT NULL DEFAULT TRUE,PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS revrec_contract_versions(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES revrec_tenants(id),contract_ref TEXT NOT NULL,version TEXT NOT NULL,framework TEXT NOT NULL CHECK(framework IN('ASC606','IFRS15')),currency CHAR(3) NOT NULL,effective_from DATE NOT NULL,contract JSONB NOT NULL,contract_digest CHAR(64) NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,contract_ref,version),UNIQUE(tenant_id,contract_digest));
CREATE TABLE IF NOT EXISTS revrec_amendments(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES revrec_tenants(id),contract_version_id BIGINT NOT NULL REFERENCES revrec_contract_versions(id),amendment_ref TEXT NOT NULL,amendment JSONB NOT NULL,treatment TEXT NOT NULL CHECK(treatment IN('prospective_separate_contract','cumulative_catch_up')),modification_digest CHAR(64) NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,contract_version_id,amendment_ref),UNIQUE(tenant_id,modification_digest));
CREATE TABLE IF NOT EXISTS revrec_periods(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES revrec_tenants(id),period_ref TEXT NOT NULL,period_start DATE NOT NULL,period_end DATE NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','review','locked')),locked_by INTEGER REFERENCES users(id),lock_evidence_digest CHAR(64),locked_at TIMESTAMPTZ,UNIQUE(tenant_id,period_ref));
CREATE TABLE IF NOT EXISTS revrec_schedules(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES revrec_tenants(id),contract_version_id BIGINT NOT NULL REFERENCES revrec_contract_versions(id),period_id BIGINT NOT NULL REFERENCES revrec_periods(id),idempotency_key TEXT NOT NULL,satisfaction_events JSONB NOT NULL,schedule JSONB NOT NULL,schedule_digest CHAR(64) NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key),UNIQUE(tenant_id,schedule_digest));
CREATE TABLE IF NOT EXISTS revrec_journal_proposals(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES revrec_tenants(id),schedule_id BIGINT NOT NULL REFERENCES revrec_schedules(id),state TEXT NOT NULL CHECK(state IN('calculated','review_pending','approved','posting_pending','posted','reconciled','locked','exception','reversed','restated')),revision INTEGER NOT NULL DEFAULT 1,journal JSONB NOT NULL,journal_digest CHAR(64) NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),supersedes_id BIGINT REFERENCES revrec_journal_proposals(id),adjustment_type TEXT CHECK(adjustment_type IN('credit','reversal','restatement')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,journal_digest));
CREATE TABLE IF NOT EXISTS revrec_approvals(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES revrec_tenants(id),journal_id BIGINT NOT NULL REFERENCES revrec_journal_proposals(id),actor_id INTEGER NOT NULL REFERENCES users(id),decision TEXT NOT NULL CHECK(decision IN('approve','reject')),attestation_digest CHAR(64) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,journal_id,actor_id));
CREATE TABLE IF NOT EXISTS revrec_posting_outbox(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES revrec_tenants(id),journal_id BIGINT NOT NULL REFERENCES revrec_journal_proposals(id),idempotency_key TEXT NOT NULL,payload JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','processing','retry','delivered','dead_letter')),attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),external_posting_id TEXT,evidence_digest CHAR(64),last_error_code TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS revrec_reconciliations(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES revrec_tenants(id),journal_id BIGINT NOT NULL REFERENCES revrec_journal_proposals(id),expected_debit_minor BIGINT NOT NULL,expected_credit_minor BIGINT NOT NULL,ledger_debit_minor BIGINT NOT NULL,ledger_credit_minor BIGINT NOT NULL,matched BOOLEAN NOT NULL,evidence_digest CHAR(64) NOT NULL,reconciled_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,journal_id,evidence_digest));
CREATE TABLE IF NOT EXISTS revrec_source_syncs(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES revrec_tenants(id),provider TEXT NOT NULL CHECK(provider IN('crm','contracts','billing','erp','usage','general_ledger','fx')),idempotency_key TEXT NOT NULL,external_cursor TEXT NOT NULL,source_version TEXT NOT NULL,source_digest CHAR(64) NOT NULL,record_count INTEGER NOT NULL CHECK(record_count>=0),reconciled BOOLEAN NOT NULL,received_at TIMESTAMPTZ NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,provider,idempotency_key),UNIQUE(tenant_id,provider,external_cursor,source_digest));
CREATE TABLE IF NOT EXISTS revrec_golden_results(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES revrec_tenants(id),fixture_version TEXT NOT NULL,result JSONB NOT NULL,evidence_digest CHAR(64) NOT NULL,passed BOOLEAN NOT NULL,evaluated_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,fixture_version,evidence_digest));
CREATE TABLE IF NOT EXISTS revrec_replays(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES revrec_tenants(id),contract_version_id BIGINT NOT NULL REFERENCES revrec_contract_versions(id),replay JSONB NOT NULL,replay_digest CHAR(64) NOT NULL,evaluated_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,contract_version_id,replay_digest));
CREATE TABLE IF NOT EXISTS revrec_audit_exports(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES revrec_tenants(id),period_id BIGINT NOT NULL REFERENCES revrec_periods(id),manifest JSONB NOT NULL,manifest_digest CHAR(64) NOT NULL,exported_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,period_id,manifest_digest));
CREATE TABLE IF NOT EXISTS revrec_failures(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES revrec_tenants(id),journal_id BIGINT REFERENCES revrec_journal_proposals(id),provider TEXT NOT NULL,operation TEXT NOT NULL,retryable BOOLEAN NOT NULL,error_code TEXT NOT NULL,sanitized_detail TEXT,occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS revrec_events(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES revrec_tenants(id),journal_id BIGINT REFERENCES revrec_journal_proposals(id),actor_id INTEGER REFERENCES users(id),event_type TEXT NOT NULL,payload JSONB NOT NULL,evidence_digest CHAR(64),occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS revrec_journal_state_idx ON revrec_journal_proposals(tenant_id,state,updated_at);CREATE INDEX IF NOT EXISTS revrec_outbox_ready_idx ON revrec_posting_outbox(status,next_attempt_at);
CREATE OR REPLACE FUNCTION prevent_revrec_evidence_mutation() RETURNS trigger AS $$BEGIN RAISE EXCEPTION 'revenue evidence is append-only';END;$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION guard_revrec_journal_evidence() RETURNS trigger AS $$BEGIN IF OLD.tenant_id<>NEW.tenant_id OR OLD.schedule_id<>NEW.schedule_id OR OLD.journal IS DISTINCT FROM NEW.journal OR OLD.journal_digest<>NEW.journal_digest OR OLD.created_by<>NEW.created_by OR OLD.supersedes_id IS DISTINCT FROM NEW.supersedes_id OR OLD.adjustment_type IS DISTINCT FROM NEW.adjustment_type OR OLD.created_at<>NEW.created_at THEN RAISE EXCEPTION 'journal evidence is immutable';END IF;RETURN NEW;END;$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION guard_revrec_period_lock() RETURNS trigger AS $$BEGIN IF OLD.status='locked' AND (NEW.status<>OLD.status OR NEW.locked_by IS DISTINCT FROM OLD.locked_by OR NEW.lock_evidence_digest IS DISTINCT FROM OLD.lock_evidence_digest OR NEW.locked_at IS DISTINCT FROM OLD.locked_at) THEN RAISE EXCEPTION 'locked accounting periods cannot be reopened or altered';END IF;RETURN NEW;END;$$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS revrec_contract_append_only ON revrec_contract_versions;CREATE TRIGGER revrec_contract_append_only BEFORE UPDATE OR DELETE ON revrec_contract_versions FOR EACH ROW EXECUTE FUNCTION prevent_revrec_evidence_mutation();
DROP TRIGGER IF EXISTS revrec_schedules_append_only ON revrec_schedules;CREATE TRIGGER revrec_schedules_append_only BEFORE UPDATE OR DELETE ON revrec_schedules FOR EACH ROW EXECUTE FUNCTION prevent_revrec_evidence_mutation();
DROP TRIGGER IF EXISTS revrec_approvals_append_only ON revrec_approvals;CREATE TRIGGER revrec_approvals_append_only BEFORE UPDATE OR DELETE ON revrec_approvals FOR EACH ROW EXECUTE FUNCTION prevent_revrec_evidence_mutation();
DROP TRIGGER IF EXISTS revrec_reconcile_append_only ON revrec_reconciliations;CREATE TRIGGER revrec_reconcile_append_only BEFORE UPDATE OR DELETE ON revrec_reconciliations FOR EACH ROW EXECUTE FUNCTION prevent_revrec_evidence_mutation();
DROP TRIGGER IF EXISTS revrec_sync_append_only ON revrec_source_syncs;CREATE TRIGGER revrec_sync_append_only BEFORE UPDATE OR DELETE ON revrec_source_syncs FOR EACH ROW EXECUTE FUNCTION prevent_revrec_evidence_mutation();
DROP TRIGGER IF EXISTS revrec_golden_append_only ON revrec_golden_results;CREATE TRIGGER revrec_golden_append_only BEFORE UPDATE OR DELETE ON revrec_golden_results FOR EACH ROW EXECUTE FUNCTION prevent_revrec_evidence_mutation();
DROP TRIGGER IF EXISTS revrec_replays_append_only ON revrec_replays;CREATE TRIGGER revrec_replays_append_only BEFORE UPDATE OR DELETE ON revrec_replays FOR EACH ROW EXECUTE FUNCTION prevent_revrec_evidence_mutation();
DROP TRIGGER IF EXISTS revrec_exports_append_only ON revrec_audit_exports;CREATE TRIGGER revrec_exports_append_only BEFORE UPDATE OR DELETE ON revrec_audit_exports FOR EACH ROW EXECUTE FUNCTION prevent_revrec_evidence_mutation();
DROP TRIGGER IF EXISTS revrec_events_append_only ON revrec_events;CREATE TRIGGER revrec_events_append_only BEFORE UPDATE OR DELETE ON revrec_events FOR EACH ROW EXECUTE FUNCTION prevent_revrec_evidence_mutation();
DROP TRIGGER IF EXISTS revrec_journal_evidence_guard ON revrec_journal_proposals;CREATE TRIGGER revrec_journal_evidence_guard BEFORE UPDATE ON revrec_journal_proposals FOR EACH ROW EXECUTE FUNCTION guard_revrec_journal_evidence();
DROP TRIGGER IF EXISTS revrec_period_lock_guard ON revrec_periods;CREATE TRIGGER revrec_period_lock_guard BEFORE UPDATE ON revrec_periods FOR EACH ROW EXECUTE FUNCTION guard_revrec_period_lock();
COMMIT;
